const isConciergeSidePanel = useMemo(
    () => isInSidePanel && isConciergeChatReport(report, conciergeReportID),
    [isInSidePanel, report, conciergeReportID]
);
```

This ensures the value is only recalculated when dependencies change and makes the derivation explicit.

